function softkom_growth_expansion_pages() {
    return array(
        'ai-automation-for-smes-south-africa' => array('title'=>'AI Automation for SMEs South Africa','eyebrow'=>'AI AUTOMATION FOR SMEs · SOUTH AFRICA','headline'=>'Practical AI automation for growing South African SMEs','intro'=>'Softkom helps SMEs automate repetitive sales, customer-service and operational work without forcing a complete technology replacement. Start with a measurable business problem, connect the tools you already use, and keep people in control of important decisions.','problems'=>array('Enquiries arrive but follow-up depends on someone remembering.','Admin increases every time sales increase.','Staff repeatedly capture or move information between tools.','Customers wait for routine answers and status updates.','You want to use AI but need a practical business case first.'),'solutions'=>array('AI lead qualification and follow-up','Customer enquiry automation with human escalation','Email, document and data-capture automation','CRM and spreadsheet integrations','Automated reminders, reporting and alerts','Phased AI adoption around measurable ROI'),'faq'=>array(array('Is AI automation affordable for an SME?','It can be when the first use case targets repetitive work with a clear cost, revenue or customer-service impact. A focused workflow is usually a better starting point than a large transformation project.'),array('Will AI automation replace our staff?','The goal is normally to remove repetitive administration and give staff better information while people remain responsible for exceptions, relationships and important decisions.'),array('What should an SME automate first?','Start with a process that happens frequently, follows repeatable steps and currently causes delays, missed opportunities or unnecessary administration.'),array('Can Softkom work with our existing software?','Yes. Where practical, Softkom integrates existing systems and spreadsheets before recommending replacement.'))),
        'replace-spreadsheets-manual-processes-south-africa' => array('title'=>'Replace Spreadsheets and Manual Processes South Africa','eyebrow'=>'WORKFLOW MODERNISATION · SOUTH AFRICA','headline'=>'Outgrown spreadsheets? Turn manual processes into a business system','intro'=>'Spreadsheets are useful until a critical process depends on multiple versions, manual updates and one person knowing how everything works. Softkom converts fragile spreadsheet-driven workflows into connected, trackable systems.','problems'=>array('Teams work from different versions of the same spreadsheet.','Information is copied between email, WhatsApp and spreadsheets.','Approvals and hand-offs are difficult to track.','Reporting requires manual consolidation.','A key process depends on one person knowing the workaround.'),'solutions'=>array('Workflow and requirements mapping','Centralised operational data','Automated approvals and notifications','Role-based workflow applications','Dashboards and management reporting','Integration with existing business software'),'faq'=>array(array('When should a business replace spreadsheets?','When spreadsheets become a shared operational system, create duplicate data, require repeated manual work or make it difficult to control access, status and reporting.'),array('Do we have to replace every spreadsheet?','No. The best approach is to modernise the processes where spreadsheet limitations create meaningful operational risk or wasted time.'),array('Can existing spreadsheet data be migrated?','Usually yes. Data can be cleaned, mapped and migrated into a structured system as part of implementation.'))),
        'sales-lead-generation-automation-south-africa' => array('title'=>'Sales and Lead Generation Automation South Africa','eyebrow'=>'SALES AUTOMATION · SOUTH AFRICA','headline'=>'Turn more enquiries into qualified sales opportunities automatically','intro'=>'Softkom builds lead-generation and sales automation systems that capture source attribution, qualify prospects, trigger follow-up and route the right opportunities to your team before good leads go cold.','problems'=>array('Website enquiries are not followed up consistently.','Salespeople spend time qualifying poor-fit leads manually.','You cannot reliably see which campaigns create revenue.','Leads sit in inboxes, spreadsheets or WhatsApp conversations.','Follow-up depends on individual sales habits.'),'solutions'=>array('Lead capture and source attribution','Automated lead scoring and qualification','AI-assisted follow-up workflows','CRM and pipeline automation','Sales alerts and routing','Campaign-to-revenue reporting'),'faq'=>array(array('What can sales automation automate?','Common workflows include lead capture, enrichment, scoring, qualification, follow-up reminders, email sequences, routing, CRM updates and reporting.'),array('Can AI qualify leads before sales contacts them?','Yes. Qualification can combine prospect answers, business rules and AI-assisted analysis while escalating strong or unusual opportunities to a person.'),array('Can we track which marketing source created a sale?','Yes. A properly designed acquisition workflow can preserve campaign and source attribution through qualification and pipeline stages.'))),
        'whatsapp-customer-service-automation-south-africa' => array('title'=>'WhatsApp and Customer Service Automation South Africa','eyebrow'=>'CUSTOMER SERVICE AUTOMATION · SOUTH AFRICA','headline'=>'Automate routine customer conversations without losing the human touch','intro'=>'Softkom helps businesses automate repetitive customer enquiries, status updates and service workflows across WhatsApp and connected channels, with clear escalation when a person should take over.','problems'=>array('Staff repeatedly answer the same customer questions.','Customers wait for simple status updates.','WhatsApp conversations are difficult to track across a team.','Enquiries are manually copied into other systems.','Important exceptions can disappear among routine messages.'),'solutions'=>array('Automated FAQ and enquiry handling','WhatsApp workflow integration','Human escalation and routing','CRM or service-system updates','Automated status notifications','Conversation and service reporting'),'faq'=>array(array('Can WhatsApp customer service be automated?','Yes. Routine questions, data collection, status updates and routing can be automated while complex or sensitive conversations are escalated to staff.'),array('Can automation connect WhatsApp to our CRM?','Where the required platform and API access are available, messages and workflow events can be connected to CRM or operational systems.'),array('Should every customer conversation use AI?','No. Automation is most useful for predictable, repetitive interactions. Human judgement remains important for exceptions, complaints and relationship-sensitive conversations.'))),
        'ai-readiness-assessment-south-africa' => array('title'=>'AI Readiness Assessment South Africa','eyebrow'=>'AI READINESS · SOUTH AFRICA','headline'=>'Find the best AI opportunities in your business before you invest','intro'=>'Softkom’s free Business Systems and AI Readiness Assessment helps South African businesses identify process bottlenecks, AI opportunities and practical next steps based on how the business operates today.','problems'=>array('You have AI ideas but no clear priority.','Different vendors recommend different tools.','You need to justify investment with business value.','Manual processes may need fixing before AI is added.','You want a practical roadmap rather than an AI experiment.'),'solutions'=>array('Business systems maturity score','AI opportunity score','Priority automation opportunities','Practical solution recommendations','Commercial next-step guidance','Strategy-call route for qualified opportunities'),'faq'=>array(array('What is an AI readiness assessment?','It evaluates processes, systems, data and operational needs to identify where AI and automation can create useful business value.'),array('Do we need technical AI knowledge?','No. The assessment is designed around business operations and outcomes rather than technical terminology.'),array('What happens after the assessment?','You receive scores and recommended opportunities. Strong-fit businesses can then discuss the highest-value next step with Softkom.')))
    );
}
function softkom_growth_expansion_html($p){$assessment=esc_url(home_url('/assessment/'));$problems='';$solutions='';$faq='';foreach($p['problems'] as $x){$problems.='<li><span>✓</span>'.esc_html($x).'</li>';}foreach($p['solutions'] as $x){$solutions.='<div class="skx-solution"><span>→</span><strong>'.esc_html($x).'</strong></div>';}foreach($p['faq'] as $x){$faq.='<details><summary>'.esc_html($x[0]).'<span>+</span></summary><p>'.esc_html($x[1]).'</p></details>';}return '<div class="skx-page"><section class="skx-hero"><div class="skx-inner"><div class="skx-pill">'.esc_html($p['eyebrow']).'</div><h1>'.esc_html($p['headline']).'</h1><p class="skx-lead">'.esc_html($p['intro']).'</p><div class="skx-actions"><a class="skx-primary" href="'.$assessment.'">Start My Free Assessment →</a><a class="skx-secondary" href="'.esc_url(home_url('/contact/')).'">Book a Strategy Call</a></div><div class="skx-proof"><span>✓ South African business focus</span><span>✓ Practical recommendations</span><span>✓ No-obligation assessment</span></div></div></section><section class="skx-main"><div class="skx-inner"><p class="skx-label">WHERE TO START</p><h2>Turn operational friction into measurable improvement</h2><div class="skx-grid"><div class="skx-problems"><h3>Common signals</h3><ul>'.$problems.'</ul></div><div class="skx-card"><p>WHAT SOFTKOM CAN DELIVER</p><h3>Practical systems. Measurable outcomes.</h3>'.$solutions.'</div></div></div></section><section class="skx-band"><div class="skx-inner"><div><p>FREE BUSINESS SYSTEMS &amp; AI READINESS ASSESSMENT</p><h2>Find your highest-value next step.</h2><span>Get a maturity score, AI opportunity score and practical recommendations.</span></div><a href="'.$assessment.'">Get My Readiness Score →</a></div></section><section class="skx-faq"><div class="skx-inner"><p class="skx-label">FREQUENTLY ASKED QUESTIONS</p><h2>What businesses need to know</h2><div class="skx-details">'.$faq.'</div></div></section><section class="skx-final"><div class="skx-inner"><p>READY TO IMPROVE THE WAY YOUR BUSINESS OPERATES?</p><h2>Start with clarity before investing in more software.</h2><a class="skx-primary" href="'.$assessment.'">Start My Free Assessment →</a></div></section></div>';}
add_action('init',function(){$version='1.0.1';if(get_option('softkom_growth_expansion_version')===$version)return;foreach(softkom_growth_expansion_pages() as $slug=>$p){$page=get_page_by_path($slug,OBJECT,'page');$post=array('post_title'=>$p['title'],'post_name'=>$slug,'post_type'=>'page','post_status'=>'publish','post_content'=>softkom_growth_expansion_html($p));if($page){$post['ID']=$page->ID;wp_update_post(wp_slash($post));}else{wp_insert_post(wp_slash($post));}}update_option('softkom_growth_expansion_version',$version,false);},21);
function softkom_growth_expansion_is_page(){return is_page()&&array_key_exists(get_post_field('post_name',get_queried_object_id()),softkom_growth_expansion_pages());}
add_filter('body_class',function($c){if(softkom_growth_expansion_is_page())$c[]='softkom-growth-expansion';return $c;});
add_filter('wp_robots',function($r){if(softkom_growth_expansion_is_page()){unset($r['noindex'],$r['nofollow']);$r['index']=true;$r['follow']=true;$r['max-image-preview']='large';}return $r;},100);
add_action('wp_head',function(){if(!softkom_growth_expansion_is_page())return;$slug=get_post_field('post_name',get_queried_object_id());$p=softkom_growth_expansion_pages()[$slug];echo '<link rel="canonical" href="'.esc_url(get_permalink()).'">'."\n";$faq=array();foreach($p['faq'] as $x){$faq[]=array('@type'=>'Question','name'=>$x[0],'acceptedAnswer'=>array('@type'=>'Answer','text'=>$x[1]));}$schema=array('@context'=>'https://schema.org','@graph'=>array(array('@type'=>'Service','name'=>$p['title'],'provider'=>array('@type'=>'Organization','name'=>'Softkom Solutions','url'=>home_url('/')),'areaServed'=>array('@type'=>'Country','name'=>'South Africa'),'url'=>get_permalink()),array('@type'=>'FAQPage','mainEntity'=>$faq)));echo '<script type="application/ld+json">'.wp_json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>'."\n";},5);
