in:34px 0 28px}.skx-primary,.skx-secondary,.skx-band a{display:inline-flex;padding:15px 21px;border-radius:10px;text-decoration:none!important;font-weight:700}.skx-primary{background:#0f172a;color:#fff!important}.skx-secondary{border:1px solid #cbd5e1;background:#fff;color:#0f172a!important}.skx-proof{display:flex;gap:24px;flex-wrap:wrap;color:#64748b;font-size:14px;font-weight:600}.skx-main,.skx-faq{padding:95px 0}.skx-label,.skx-card>p,.skx-band p,.skx-final p{margin:0 0 10px;color:#2563eb;font-size:12px;font-weight:800;letter-spacing:.09em}.skx-page h2{max-width:800px;margin:0 0 42px;color:#0f172a;font-size:clamp(32px,4vw,50px);line-height:1.08;letter-spacing:-.035em}.skx-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:34px}.skx-problems,.skx-card{padding:34px;border:1px solid #e2e8f0;border-radius:20px}.skx-problems h3,.skx-card h3{margin:0 0 22px;font-size:25px;color:#0f172a}.skx-problems ul{list-style:none;margin:0;padding:0}.skx-problems li{display:flex;gap:12px;padding:13px 0;border-bottom:1px solid #f1f5f9;line-height:1.5}.skx-problems li span{color:#22c55e;font-weight:800}.skx-card{background:#0f172a;border-color:#0f172a}.skx-card h3{color:#fff}.skx-solution{display:flex;gap:10px;padding:13px;margin:10px 0;background:#172033;border:1px solid #263247;border-radius:11px;color:#e2e8f0}.skx-solution span{color:#60a5fa}.skx-band{padding:62px 0;background:#0f172a;color:#cbd5e1}.skx-band .skx-inner{display:flex;align-items:center;justify-content:space-between;gap:35px}.skx-band h2{color:#fff;margin-bottom:12px}.skx-band span{font-size:17px}.skx-band a{flex:none;background:#2563eb;color:#fff!important}.skx-faq{background:#f8fafc}.skx-details{max-width:900px}.skx-details details{padding:22px 0;border-bottom:1px solid #cbd5e1}.skx-details summary{display:flex;justify-content:space-between;cursor:pointer;list-style:none;color:#0f172a;font-size:18px;font-weight:700}.skx-details summary::-webkit-details-marker{display:none}.skx-details summary span{color:#2563eb}.skx-details p{max-width:760px;line-height:1.7;color:#475569}.skx-final{padding:85px 0;text-align:center}.skx-final h2{margin:0 auto 28px}.skx-final .skx-primary{margin:auto}@media(max-width:800px){.skx-inner{width:min(100% - 32px,1180px)}.skx-hero{padding:70px 0 60px}.skx-grid{grid-template-columns:1fr}.skx-band .skx-inner{flex-direction:column;align-items:flex-start}.skx-main,.skx-faq{padding:70px 0}.skx-proof{flex-direction:column;gap:10px}}');},30);
